/* Krushivikas 2026 / bootstrap */
function render(){if(sensorUnsub&&currentRoute()!=='sensors'){sensorUnsub();sensorUnsub=null;}state.route=currentRoute();state.mobile=false;let page='',load=()=>{};switch(state.route){case 'home':page=landing();break;case 'platform':page=platform();break;case 'marketplace':page=marketplacePage();load=loadMarketplace;break;case 'markets':page=marketsPage();load=()=>{loadMandi();loadForecast();loadPriceHistory();loadMarketPrices();};break;case 'diagnostics':page=diagnosticPage();break;case 'soil':page=soilPage();break;case 'trace':page=tracePage();break;case 'login':page=loginPage();break;case 'register':page=registerPage();break;case 'dashboard':page=dashboardPage();load=loadDashboard;break;case 'farm':page=farmPage();load=loadFarm;break;case 'records':page=recordsPage();load=loadRecords;break;case 'orders':page=ordersPage();load=loadOrders;break;case 'review':page=reviewPage();load=loadReview;break;case 'operations':page=opsPage();load=loadOps;break;case 'insights':page=insightsPage();load=loadInsights;break;case 'sensors':page=sensorsPage();load=loadSensors;break;default:page=`${heading('A path yet to grow.','404 / NOT FOUND','We could not find that page.',photo.land)}<section class="page-main"><a class="button" href="#/home">Return home ↗</a></section>${footer()}`;}
 root.innerHTML=header()+page;document.title=`${({home:'Grounded in the future',platform:'Our platform',marketplace:'Marketplace',markets:'Market intelligence',diagnostics:'Crop health',soil:'Soil advisory',trace:'Traceability',login:'Sign in',register:'Create account',dashboard:'Workspace',farm:'My farm',records:'Farm journal',orders:'Orders',review:'Harvest review',operations:'Supply chain',insights:'Analytics',sensors:'Live sensors'})[state.route]||'Krushivikas'} — Krushivikas`;
 try{load();}catch(e){console.error('Page load failed',e);}if(state.route==='trace'&&new URLSearchParams(location.search).has('id'))$('#trace-form')?.requestSubmit();}
state.loginRole='buyer';state.registerRole='buyer';state.reviewTab='pending';
window.addEventListener('hashchange',()=>{window.scrollTo(0,0);render();});
document.addEventListener('click',async e=>{
 const role=e.target.closest('[data-role]');if(role){state.loginRole=role.dataset.role;render();return;}
 const register=e.target.closest('[data-register]');if(register){state.registerRole=register.dataset.register;render();return;}
 const tab=e.target.closest('[data-tab]');if(tab){state.tab=tab.dataset.tab;$('#records-table').innerHTML=recordsTable();$$('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===state.tab));$('.workspace-head h1')?.replaceChildren(document.createTextNode('Your '+state.tab+'.'));return;}
 const reviewTab=e.target.closest('[data-review]');if(reviewTab){state.reviewTab=reviewTab.dataset.review;$$('[data-review]').forEach(b=>b.classList.toggle('active',b.dataset.review===state.reviewTab));loadReview();return;}
 const a=e.target.closest('[data-action]');if(!a)return;const action=a.dataset.action,id=a.dataset.id;
 switch(action){case 'mobile':state.mobile=!state.mobile;$('.mobile-menu')?.classList.toggle('open',state.mobile);break;case 'logout':logout();break;case 'close-modal':$('#modal-root')?.remove();break;case 'retry':render();break;case 'filter-market':loadMarketplace();break;case 'reset-market':$('#market-location').value='';loadMarketplace();break;case 'order':createOrder(a);break;case 'new-listing':newListing();break;case 'order-status':changeOrder(id,a.dataset.status);break;case 'edit-profile':editFarm();break;case 'add-log':addLog();break;case 'update-plan':updatePlan(id);break;case 'approve-harvest':reviewHarvest(id,'approve');break;case 'reject-harvest':reviewHarvest(id,'reject');break;case 'evidence':attachEvidence(id);break;case 'view-evidence':viewEvidence(id);break;case 'verify-harvest':verifyHarvest(id);break;case 'add-operation':addOperation();break;case 'edit-operation':editOperation(id);break;case 'delete-operation':deleteOperation(id);break;case 'chain':traceChain(id);break;default:break;}
});
document.addEventListener('change',e=>{if(e.target.id==='ops-select'){state.operations=e.target.value;render();}if(e.target.id==='disease-image'&&e.target.files?.[0]){const img=$('#disease-preview');img.src=URL.createObjectURL(e.target.files[0]);img.classList.remove('hide');}});
document.addEventListener('submit',e=>{if(e.target.id==='login-form')authSubmit(e);else if(e.target.id==='register-form')authSubmit(e,true);else if(e.target.id==='disease-form')diseaseSubmit(e);else if(e.target.id==='soil-form')soilSubmit(e);else if(e.target.id==='trace-form')traceSubmit(e);else if(e.target.id==='mandi-form'){e.preventDefault();loadMandi(formData(e.target));}});
render();
